"""Импорт банковских выписок.

Поддерживаются форматы (определяются по заголовку):

    nova         date,amount,description               (разделитель «,»)
    sfera        Дата;Сумма;Описание                   (разделитель «;»)
    sfera_split  Дата;Описание;Приход;Расход           (разделитель «;»)

Конвейер: декодирование → формат → разбор всего файла → дедупликация →
одна запись ``store.add_many``. Пока файл не разобран целиком, хранилище
не меняется.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, field, replace
from decimal import Decimal
from pathlib import Path

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount, to_money
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

_SFERA_DATE = re.compile(r"[0-9]{2}\.[0-9]{2}\.[0-9]{4}")
_SFERA_AMOUNT = re.compile(r"[+-]?(\d{1,3}([  ]\d{3})+|\d+)(,\d{1,2})?", re.ASCII)


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError] = field(default_factory=list)


@dataclass(frozen=True)
class _Spec:
    delimiter: str
    columns: dict[str, str]  # логическое имя -> название колонки в файле
    exact: bool  # True: точные имена; False: без регистра и краевых пробелов


_SPECS: dict[str, _Spec] = {
    "nova": _Spec(",", {"date": "date", "amount": "amount", "description": "description"}, True),
    "sfera": _Spec(";", {"date": "дата", "amount": "сумма", "description": "описание"}, False),
    "sfera_split": _Spec(
        ";",
        {"date": "дата", "description": "описание", "income": "приход", "expense": "расход"},
        False,
    ),
}


def normalize_description(text: str) -> str:
    """Приводит описание к виду для поиска дублей (как везде в проекте)."""
    return normalize_text(text)


def _decode(data: bytes) -> tuple[str, str]:
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("cannot decode file as utf-8 or cp1251") from exc


def _reader(text: str, delimiter: str):
    return csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)


def _match_header(spec: _Spec, header: list[str]) -> dict[str, int] | None:
    """Карта «логическая колонка → индекс» или None, если заголовок не подходит."""
    names = header if spec.exact else [h.strip().casefold() for h in header]
    result: dict[str, int] = {}
    for key, wanted in spec.columns.items():
        found = [i for i, n in enumerate(names) if n == wanted]
        if len(found) != 1:
            return None
        result[key] = found[0]
    return result


def _detect(text: str, fmt: str | None) -> tuple[str, dict[str, int]]:
    if not text:
        raise UnknownFormatError("empty file")
    if fmt is not None and fmt not in _SPECS:
        raise UnknownFormatError(f"unknown format {fmt!r}", line_no=1)
    matched: list[tuple[str, dict[str, int]]] = []
    for name in (fmt,) if fmt else _SPECS:
        try:
            header = next(_reader(text, _SPECS[name].delimiter), None)
        except csv.Error:
            header = None
        columns = _match_header(_SPECS[name], header) if header is not None else None
        if columns is not None:
            matched.append((name, columns))
    if len(matched) > 1:
        raise UnknownFormatError("ambiguous header", line_no=1)
    if not matched:
        what = f"header does not match format {fmt!r}" if fmt else "unrecognized header"
        raise UnknownFormatError(what, line_no=1)
    return matched[0]


def detect_format(path: str | os.PathLike[str]) -> str:
    """Определяет формат выписки по заголовку или бросает UnknownFormatError."""
    text, _ = _decode(Path(path).read_bytes())
    return _detect(text, None)[0]


class _RowProblem(Exception):
    """Внутреннее: строку нельзя разобрать (сообщение без номера строки)."""


def _parse_date(value: str, iso: bool) -> dt.date:
    value = value.strip()
    try:
        if iso:
            return dt.date.fromisoformat(value)
        if not _SFERA_DATE.fullmatch(value):
            raise ValueError(value)
        return dt.date(int(value[6:]), int(value[3:5]), int(value[:2]))
    except ValueError:
        raise _RowProblem(f"invalid date {value!r}") from None


def _parse_sfera_amount(value: str, *, signed: bool) -> Decimal:
    cleaned = value.strip()
    if not signed and cleaned[:1] in ("+", "-"):
        raise _RowProblem(f"sign is not allowed in amount {cleaned!r}")
    if not _SFERA_AMOUNT.fullmatch(cleaned):
        raise _RowProblem(f"invalid amount {cleaned!r}")
    number = cleaned.replace(" ", "").replace(" ", "").replace(",", ".")
    try:
        return to_money(Decimal(number))
    except ValidationError as exc:
        raise _RowProblem(str(exc)) from None


def _build_row(
    fmt: str, cols: dict[str, int], row: list[str], imported_at: dt.datetime
) -> Transaction:
    if len(row) <= max(cols.values()):
        raise _RowProblem("not enough fields")
    date = _parse_date(row[cols["date"]], iso=fmt == "nova")
    if fmt == "nova":
        try:
            amount = parse_amount(row[cols["amount"]])
        except ValidationError as exc:
            raise _RowProblem(str(exc)) from None
    elif fmt == "sfera":
        amount = _parse_sfera_amount(row[cols["amount"]], signed=True)
    else:
        income_raw = row[cols["income"]].strip()
        expense_raw = row[cols["expense"]].strip()
        income = _parse_sfera_amount(income_raw, signed=False) if income_raw else Decimal(0)
        expense = _parse_sfera_amount(expense_raw, signed=False) if expense_raw else Decimal(0)
        if (income != 0) == (expense != 0):
            raise _RowProblem("exactly one of income/expense must be filled")
        amount = income if income != 0 else -expense
    try:
        return Transaction(
            date=date,
            amount=amount,
            description=row[cols["description"]].strip(),
            imported_at=imported_at,
        )
    except ValidationError as exc:
        raise _RowProblem(str(exc)) from None


def _parse_rows(
    text: str, fmt: str, cols: dict[str, int], imported_at: dt.datetime
) -> list[Transaction | RowError]:
    reader = _reader(text, _SPECS[fmt].delimiter)
    next(reader)  # заголовок
    out: list[Transaction | RowError] = []
    while True:
        line_no = reader.line_num + 1
        try:
            row = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            out.append(RowError(line_no, str(exc)))
            if reader.line_num < line_no:
                break
            continue
        if all(not value.strip() for value in row):
            continue
        try:
            out.append(_build_row(fmt, cols, row, imported_at))
        except _RowProblem as exc:
            out.append(RowError(line_no, str(exc)))
    return out


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store: автоформат, без дублей, одной атомарной записью."""
    clock = clock or SystemClock()
    imported_at = clock.now()
    text, encoding = _decode(Path(path).read_bytes())
    fmt, cols = _detect(text, fmt)
    parsed = _parse_rows(text, fmt, cols, imported_at)

    errors = [item for item in parsed if isinstance(item, RowError)]
    if strict and errors:
        raise StatementRowError(errors[0].message, line_no=errors[0].line_no)

    existing = Counter(
        (tx.date, tx.amount, normalize_description(tx.description)) for tx in store.all()
    )
    new: list[Transaction] = []
    duplicates = 0
    for item in parsed:
        if isinstance(item, RowError):
            continue
        key = (item.date, item.amount, normalize_description(item.description))
        if existing[key] > 0:
            existing[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(item)
            if category is not None:
                item = replace(item, category=category)
        new.append(item)

    if new:
        store.add_many(new)
    logger.info(
        "imported %d transactions from %s (%s, %d duplicates, %d errors)",
        len(new), path, fmt, duplicates, len(errors),
    )
    return ImportResult(fmt, encoding, len(new), duplicates, errors)


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку «Новы» в store и возвращает число добавленных транзакций."""
    return import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    ).added

"""Иерархия исключений проекта.

Весь код ledger бросает только наследников LedgerError, чтобы CLI и
вызывающий код могли перехватывать ошибки предметной области одним except.
"""

from __future__ import annotations


class LedgerError(Exception):
    """Базовое исключение ledger."""


class ValidationError(LedgerError):
    """Некорректные данные модели (сумма, дата, описание и т.п.)."""


class StorageError(LedgerError):
    """Ошибка чтения или записи хранилища."""


class StatementError(LedgerError):
    """Ошибка разбора банковской выписки.

    line_no — номер строки файла, если ошибка относится к конкретной строке;
    иначе None. Нумерация по физическим строкам файла: заголовок — строка 1,
    пустые строки тоже считаются; если запись в кавычках занимает несколько
    строк, её номер — строка, где она начинается.
    """

    def __init__(self, message: str, *, line_no: int | None = None) -> None:
        text = message if line_no is None else f"line {line_no}: {message}"
        super().__init__(text)
        self.message = message
        self.line_no = line_no


class UnknownFormatError(StatementError):
    """Формат или кодировка выписки не распознаны (или не подходят к заданному fmt)."""


class StatementRowError(StatementError):
    """Ошибка конкретной строки выписки в строгом режиме; line_no обязателен."""

    def __init__(self, message: str, *, line_no: int) -> None:
        super().__init__(message, line_no=line_no)

